"""Half-open integer interval utilities.

An interval is a pair (start, end) meaning the half-open range [start, end).
A pair with start >= end is empty and ignored everywhere.
All public functions return lists of (start, end) tuples sorted by start.
"""

from typing import Iterable, List, Sequence, Tuple

Interval = Tuple[int, int]


def _clean(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Return non-empty intervals as (start, end) tuples, sorted by start."""
    out: List[Interval] = []
    for a, b in intervals:
        if a < b:
            out.append((a, b))
    out.sort(key=lambda p: (p[0], p[1]))
    return out


def merge(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Merge overlapping and touching intervals."""
    result: List[Interval] = []
    for start, end in _clean(intervals):
        if result and start <= result[-1][1]:
            # Overlapping or touching: extend previous interval's end if needed.
            if end > result[-1][1]:
                result[-1] = (result[-1][0], end)
        else:
            result.append((start, end))
    return result


def free_gaps(intervals: Iterable[Sequence[int]], window: Sequence[int]) -> List[Interval]:
    """Maximal sub-ranges of [ws, we) not covered by any interval, in order."""
    ws, we = window
    if ws >= we:
        return []

    merged = []
    for start, end in merge(intervals):
        # Clip to the window; ignore fully outside ones.
        s = max(start, ws)
        e = min(end, we)
        if s < e:
            merged.append((s, e))

    gaps: List[Interval] = []
    cursor = ws
    for s, e in merged:
        if cursor < s:
            gaps.append((cursor, s))
        cursor = e
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals: Iterable[Sequence[int]]) -> int:
    """Largest number of non-empty intervals covering one common point."""
    events: List[Tuple[int, int]] = []
    for a, b in intervals:
        if a < b:
            # Ends (-1) must sort before starts (+1) at equal positions so
            # half-open touching intervals do not count as overlapping.
            events.append((a, 1))
            events.append((b, -1))
    if not events:
        return 0
    events.sort(key=lambda e: (e[0], e[1]))
    depth = 0
    best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live (see README.md in this directory)."""

import time
from collections import OrderedDict

_MISSING = object()


class TTLCache:
    """An LRU cache in which entries can carry an individual lifetime."""

    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.clock = clock
        # key -> (value, expires_at); expires_at is None for immortal entries.
        # OrderedDict preserves least-recently-used -> most-recently-used order.
        self._data = OrderedDict()

    @staticmethod
    def _expired(expires_at, now):
        return expires_at is not None and now >= expires_at

    def _purge(self, now):
        """Delete every expired entry; return how many were removed."""
        expired = [k for k, (_v, exp) in self._data.items()
                   if self._expired(exp, now)]
        for key in expired:
            del self._data[key]
        return len(expired)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self.clock()
        expires_at = None if ttl is None else now + ttl
        if key in self._data:
            # Replace value, restart lifetime, bump to most recently used.
            self._data.move_to_end(key)
            self._data[key] = (value, expires_at)
            return
        if len(self._data) >= self.capacity:
            self._purge(now)
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)  # evict least recently used
        self._data[key] = (value, expires_at)

    def get(self, key, default=None):
        entry = self._data.get(key, _MISSING)
        if entry is _MISSING:
            return default
        value, expires_at = entry
        if self._expired(expires_at, self.clock()):
            del self._data[key]
            return default
        self._data.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._data.get(key, _MISSING)
        if entry is _MISSING:
            return False
        # Intentionally does not change recency and does not purge.
        return not self._expired(entry[1], self.clock())

    def __len__(self):
        self._purge(self.clock())
        return len(self._data)

    def keys(self):
        self._purge(self.clock())
        return list(self._data.keys())

    def evict_expired(self):
        return self._purge(self.clock())

"""Arithmetic expression evaluator.

Implements ``evaluate(text)`` per the README spec using a hand-written
tokenizer and a recursive-descent parser (no eval/exec/compile/ast).

Grammar (mirrors Python precedence):

    expr   := term (('+' | '-') term)*
    term   := unary (('*' | '/' | '//' | '%') unary)*
    unary  := ('+' | '-') unary | power
    power  := atom ('**' unary)?          # right-associative
    atom   := NUMBER | '(' expr ')' | CALL
    CALL   := ('min' | 'max') '(' expr (',' expr)* ')'
            | 'abs' '(' expr ')'
"""

import re

_NUMBER_RE = re.compile(r"\d+(\.\d+)?|\.\d+")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")
_TWO_CHAR_OPS = ("**", "//")
_SINGLE_CHARS = "+-*/%(),"


def evaluate(text: str):
    """Parse and evaluate *text*; return an int or float."""
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    tokens = _tokenize(text)
    return _Parser(tokens).parse()


def _tokenize(text):
    tokens = []
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        m = _NUMBER_RE.match(text, i)
        if m is not None:
            word = m.group(0)
            tokens.append(("num", float(word) if "." in word else int(word)))
            i = m.end()
            continue
        m = _IDENT_RE.match(text, i)
        if m is not None:
            tokens.append(("name", m.group(0)))
            i = m.end()
            continue
        if text[i:i + 2] in _TWO_CHAR_OPS:
            tokens.append(("op", text[i:i + 2]))
            i += 2
            continue
        if ch in _SINGLE_CHARS:
            tokens.append(("op", ch))
            i += 1
            continue
        raise ValueError("unexpected character %r" % ch)
    tokens.append(("eof", None))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    # -- token helpers -------------------------------------------------
    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect_op(self, op):
        kind, val = self.advance()
        if kind != "op" or val != op:
            raise ValueError("expected %r" % op)

    # -- grammar -------------------------------------------------------
    def parse(self):
        if self.peek()[0] == "eof":
            raise ValueError("empty expression")
        value = self.expr()
        if self.peek()[0] != "eof":
            raise ValueError("unexpected trailing token %r" % (self.peek()[1],))
        return value

    def expr(self):
        value = self.term()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("+", "-"):
                self.advance()
                rhs = self.term()
                value = value + rhs if val == "+" else value - rhs
            else:
                return value

    def term(self):
        value = self.unary()
        while True:
            kind, val = self.peek()
            if kind == "op" and val in ("*", "/", "//", "%"):
                self.advance()
                rhs = self.unary()
                if val == "*":
                    value = value * rhs
                elif val == "/":
                    value = value / rhs
                elif val == "//":
                    value = value // rhs
                else:
                    value = value % rhs
            else:
                return value

    def unary(self):
        kind, val = self.peek()
        if kind == "op" and val in ("+", "-"):
            self.advance()
            value = self.unary()
            return value if val == "+" else -value
        return self.power()

    def power(self):
        base = self.atom()
        kind, val = self.peek()
        if kind == "op" and val == "**":
            self.advance()
            exponent = self.unary()  # right-associative, unary in exponent
            return base ** exponent
        return base

    def atom(self):
        kind, val = self.advance()
        if kind == "num":
            return val
        if kind == "op" and val == "(":
            value = self.expr()
            self.expect_op(")")
            return value
        if kind == "name":
            if self.peek() == ("op", "("):
                return self.call(val)
            raise ValueError("unknown name %r" % val)
        if kind == "eof":
            raise ValueError("missing operand")
        raise ValueError("unexpected token %r" % val)

    def call(self, name):
        self.advance()  # consume '('
        args = []
        kind, val = self.peek()
        if not (kind == "op" and val == ")"):
            args.append(self.expr())
            while self.peek() == ("op", ","):
                self.advance()
                args.append(self.expr())
        self.expect_op(")")
        if name in ("min", "max"):
            if not args:
                raise ValueError("%s requires at least one argument" % name)
            return min(args) if name == "min" else max(args)
        if name == "abs":
            if len(args) != 1:
                raise ValueError("abs takes exactly one argument")
            return abs(args[0])
        raise ValueError("unknown function %r" % name)
